(44, 1063, 9, 26, 1, 1, 1, 'ঢাকায় পুলিশের গাড়িতে আগুনের ঘটনায় দুজন গ্রেপ্তার', '', NULL, 'public/postimages/654aaa12de891.png', 'এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!', '<p>এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!<br>', 'nbbvvn', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, NULL),
(45, 1062, 2, 3, 1, 1, 1, 'আশুলিয়ায় বন্ধ ৬০ পোশাক কারখানা, ১২ মামলায় আসামি সাড়ে ৩ হাজার', NULL, NULL, 'public/postimages/6550847775045.png', 'ন্যূনতম মজুরি প্রত্যাখ্যান করে পোশাকশ্রমিকদের চলমান আন্দোলনের জেরে ঢাকার অদূরে সাভারের আশুলিয়ায় আজ রোববার ৬০টি পোশাক কারখানা বন্ধ আছে। গতকাল শনিবার সাভার, আশুলিয়া ও ধামরাইয়ে মোট বন্ধ কারখানার সংখ্যা ছিল ১৩০।', '<p>ন্যূনতম মজুরি প্রত্যাখ্যান করে পোশাকশ্রমিকদের চলমান আন্দোলনের জেরে ঢাকার অদূরে সাভারের আশুলিয়ায় আজ রোববার ৬০টি পোশাক কারখানা বন্ধ আছে। গতকাল শনিবার সাভার, আশুলিয়া ও ধামরাইয়ে মোট বন্ধ কারখা', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '45/আশুলিয়ায়-বন্ধ-৬০-পোশাক-কারখানা,-১২-মামলায়-আসামি-সাড়ে-৩-হাজার'),
(46, 1062, 2, 3, 1, 1, 1, '১৬ দিন ধরে বিএনপি কার্যালয়ে ঝুলছে তালা, সামনে পুলিশ', NULL, NULL, 'public/postimages/655084deab5d8.png', 'রাজধানীর নয়াপল্টনে বিএনপির কেন্দ্রীয় কার্যালয়ের মূল ফটকে ১৬ দিন ধরে তালা ঝুলছে। কার্যালয়ের সামনে অবস্থান করছে পুলিশ।আজ রোববার সকাল ১০টার দিকে বিএনপির কেন্দ্রীয় কার্যালয় এলাকায় গিয়ে এমন চিত্র দেখা গেছে।', '<p>রাজধানীর নয়াপল্টনে বিএনপির কেন্দ্রীয় কার্যালয়ের মূল ফটকে ১৬ দিন ধরে তালা ঝুলছে। কার্যালয়ের সামনে অবস্থান করছে পুলিশ।<span style=\"font-size: 1rem;\">আজ রোববার সকাল ১০টার দিকে বিএনপির কেন্', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '46/১৬-দিন-ধরে-বিএনপি-কার্যালয়ে-ঝুলছে-তালা,-সামনে-পুলিশ'),
(47, 1063, 2, 3, 1, 1, 1, 'নারায়ণগঞ্জে পার্কিং করা গাড়ি ভাঙচুর, আগুন', NULL, NULL, 'public/postimages/6550853da1509.png', 'নারায়ণগঞ্জ সদর উপজেলার সিদ্ধিরগঞ্জে পার্কিং করা একটি গাড়ি ভাঙচুর ও আগুন দেওয়ার ঘটনা ঘটেছে। গতকাল শনিবার গভীর রাতে এ ঘটনা ঘটে। তবে এতে কোনো হতাহতের ঘটনা ঘটেনি।', '<p>নারায়ণগঞ্জ সদর উপজেলার সিদ্ধিরগঞ্জে পার্কিং করা একটি গাড়ি ভাঙচুর ও আগুন দেওয়ার ঘটনা ঘটেছে। গতকাল শনিবার গভীর রাতে এ ঘটনা ঘটে। তবে এতে কোনো হতাহতের ঘটনা ঘটেনি।</p><p><span style=\"font-size:', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '47/নারায়ণগঞ্জে-পার্কিং-করা-গাড়ি-ভাঙচুর,-আগুন'),
(48, 1062, 5, 7, 1, 1, 1, 'রাজধানীতে অবরোধের সমর্থনে বিএনপি ও অঙ্গসংগঠনের ঝটিকা মিছিল', NULL, NULL, 'public/postimages/65509feeda191.png', 'চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠনগুলোর দেওয়া প্রেস বিজ্ঞপ্তিতে এ তথ্য জানা যায়।', '<p>চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ<span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ</span><span style=\"font-size: 1rem;\">চতুর্থ দফা অবরোধের প্রথম দিন 