(49, 1063, 8, 12, 1, 1, 1, 'কখনো স্কুলেই যাননি এই নায়িকা', NULL, NULL, 'public/postimages/655099fbdf238.png', 'মাত্র ১৪ বছর বয়সে মডেলিং শুরু করেন ক্যাটরিনা। এর কিছুদিন পরই লন্ডনভিত্তিক নির্মাতা কাইজাদ গুস্তাবের চোখে পড়েন। তাঁর পরিচালনায় ২০০৩ সালে ‘বুম’ সিনেমায় সুযোগ পান ক্যাটরিনা। এ সিনেমায় ছিলেন অমিতাভ বচ্চনও', '<p><span style=\"color: rgb(18, 18, 18); font-family: Shurjo, SolaimanLipi, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; font-size: 18px;\">মাত্র ১৪ বছর বয়সে মডেলিং শুরু করেন', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '49/কখনো-স্কুলেই-যাননি-এই-নায়িকা'),
