(51, 1062, 2, 3, 1, 1, 1, 'মিরপুরে আড়াই ঘণ্টা পর রাস্তা ছাড়লেন পোশাকশ্রমিকেরা', NULL, NULL, 'public/postimages/65508617984ee.png', 'আড়াই ঘণ্টা পর রাজধানীর মিরপুর-১৩ ও মিরপুর-১০ নম্বর এলাকার রাস্তা ছাড়েন পোশাক কারখানার শ্রমিকেরা।আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর ১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুরু করেন। সকাল সাড়ে ১০টার দিকে তাঁরা সরে যান বলে জানিয়েছে পুলিশ।', '<p>আড়াই ঘণ্টা পর রাজধানীর মিরপুর-১৩ ও মিরপুর-১০ নম্বর এলাকার রাস্তা ছাড়েন পোশাক কারখানার শ্রমিকেরা।<span style=\"font-size: 1rem;\">আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর ১৩ নম্বর সড়কের দুই প', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '51/মিরপুরে-আড়াই-ঘণ্টা-পর-রাস্তা-ছাড়লেন-পোশাকশ্রমিকেরা'),
(52, 1063, 2, 3, 1, 1, 1, 'বগুড়ায় মহাসড়ক অবরোধ করে বিএনপি নেতা-কর্মীদের বিক্ষোভ', NULL, NULL, 'public/postimages/6550869161c9b.png', 'বিএনপির ডাকা চতুর্থ দফায় সারা দেশে ৪৮ ঘণ্টার সড়ক, রেল ও নৌপথ অবরোধের প্রথম দিন বগুড়ায় মহাসড়কে অবস্থান নিয়ে বিক্ষোভ করেছেন দলটির নেতা-কর্মীরা। আজ রোববার সকাল থেকে ঢাকা-রংপুর মহাসড়কের বগুড়ার শাজাহানপুর উপজেলার বনানী-লিচুতলায় বাইপাস সড়কে অবস্থান নিয়ে বিক্ষোভ করছেন তাঁরা।', '<p>বিএনপির ডাকা চতুর্থ দফায় সারা দেশে ৪৮ ঘণ্টার সড়ক, রেল ও নৌপথ অবরোধের প্রথম দিন বগুড়ায় মহাসড়কে অবস্থান নিয়ে বিক্ষোভ করেছেন দলটির নেতা-কর্মীরা। আজ রোববার সকাল থেকে ঢাকা-রংপুর মহাসড়কের বগুড়ার', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '52/বগুড়ায়-মহাসড়ক-অবরোধ-করে-বিএনপি-নেতা-কর্মীদের-বিক্ষোভ'),
(53, 1063, 2, 3, 1, 1, 1, 'গাজীপুরে শ্রমিক-পুলিশ সংঘর্ষে আহত আরেক শ্রমিকের মৃত্যু', NULL, NULL, 'public/postimages/655087031675c.png', 'গাজীপুর মহানগরীর কোনাবাড়ীর জরুন এলাকায় শ্রমিক ও পুলিশের মধ্যে সংঘর্ষের ঘটনায় আহত আরেক শ্রমিক মারা গেছেন। ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালে চিকিৎসাধীন অবস্থায় গতকাল শনিবার দিবাগত রাত সাড়ে ১২টার দিকে মো. জালাল উদ্দিন (৪০) নামের ওই শ্রমিকের মৃত্যু হয়।', '<p>গাজীপুর মহানগরীর কোনাবাড়ীর জরুন এলাকায় শ্রমিক ও পুলিশের মধ্যে সংঘর্ষের ঘটনায় আহত আরেক শ্রমিক মারা গেছেন। ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালে চিকিৎসাধীন অবস্থায় গতকাল শনিবার দিবাগত রাত সাড়ে', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '53/গাজীপুরে-শ্রমিক-পুলিশ-সংঘর্ষে-আহত-আরেক-শ্রমিকের-মৃত্যু'),
(54, 1063, 2, 3, 1, 1, 1, 'মিরপুরে রাস্তায় নেমে পোশাকশ্রমিকদের বিক্ষোভ', NULL, NULL, 'public/postimages/655087dab1052.png', 'রাজধানীর মিরপুর–১০, ১৩ ও পল্লবী এলাকার রাস্তা অবরোধ করে বিক্ষোভ করছেন পোশাক কারখানার কয়েক শ শ্রমিক। আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর–১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুরু করেন।', '<p>রাজধানীর মিরপুর–১০, ১৩ ও পল্লবী এলাকার রাস্তা অবরোধ করে বিক্ষোভ করছেন পোশাক কারখানার কয়েক শ শ্রমিক। আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর–১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুর', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '51/মিরপুরে-আড়াই-ঘণ্টা-পর-রাস্তা-ছাড়লেন-পোশাকশ্রমিকেরা'),
(55, 1063, 2, 3, 1, 1, 1, '‘এক হাতে রিকশা চালাইতে কষ্ট অইলেও সম্মান নিয়া চলতাম পারি’', NULL, NULL, 'public/postimages/6550885af30e7.png', 'তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হয়। সেই দুর্ঘটনা শুধু তাঁর শৈশবকেই তছনছ করেনি, স্থায়ী কষ্টের মধ্যে ফেলে দিয়েছে।', '<p>তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '55/‘এক-হাতে-রিকশা-চালাইতে-কষ্ট-অইলেও-সম্মান-নিয়া-চলতাম-পারি’'),
(56, 1062, 5, 6, 1, 1, 1, 'সিলেটে সড়কে গুঁড়ি ফেলে, আগুন জ্বালিয়ে অবরোধ, স্বেচ্ছাসেবক দলের নেতা আটক', NULL, NULL, 'public/postimages/65509f747df87.png', 'বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের সময় এক স্বেচ্ছাসেবক দলের নেতাকে আটক করেছে পুলিশ। আটক মামুনুর রশীদ সিলেট মহানগর ১৭ নম্বর ওয়ার্ড স্বেচ্ছাসেবক দলের আহ্বায়ক।', '<p>বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের<span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের</span><span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের</span><span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের</span><span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের</span><span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের</span><span style=\"font-size: 1rem;\">বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ