(68, 1063, 7, 9, 1, 1, 1, 'দেশে ফিরেছে বাংলাদেশ দল, কোচদের মধ্যে এসেছেন শুধু হাথুরুসিংহে', NULL, NULL, 'public/postimages/6550815455e13.png', 'বাংলাদেশ দল গতকালই বিশ্বকাপের প্রথম পর্বে তাদের শেষ ম্যাচটি খেলেছে। অস্ট্রেলিয়ার বিপক্ষে পুনেতে ৮ উইকেটে হেরেছে বাংলাদেশ দল। এ নিয়ে লিগ পর্বের ৯টি ম্যাচ খেলে বাংলাদেশ জিতেছে মাত্র ২টিতে। বিশ্বকাপের ব্যর্থ মিশন শেষে বাংলাদেশ দল আজ সকালে পৌনে ১০টায় ঢাকায় পৌঁছেছে।', '<p>বাংলাদেশ দল গতকালই বিশ্বকাপের প্রথম পর্বে তাদের শেষ ম্যাচটি খেলেছে। অস্ট্রেলিয়ার বিপক্ষে পুনেতে ৮ উইকেটে হেরেছে বাংলাদেশ দল। এ নিয়ে লিগ পর্বের ৯টি ম্যাচ খেলে বাংলাদেশ জিতেছে মাত্র ২টিতে। ব', 'sports', NULL, 1, 1, 1, 1, '09-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '68/দেশে-ফিরেছে-বাংলাদেশ-দল,-কোচদের-মধ্যে-এসেছেন-শুধু-হাথুরুসিংহে'),
(69, 1062, 7, 10, 1, 1, 1, 'কেইনের রেকর্ড, এমবাপ্পের হ্যাটট্রিকেও খুশি নন এনরিকে', NULL, NULL, 'public/postimages/6550825cdbdb2.png', 'লিগ বদলেছে, দল বদলেছে, কিন্তু বদলাননি হ্যারি কেইন। বদলায়নি তাঁর গোল করার ধারাও। বুন্দেসলিগায় হেইডেনহেইমের বিপক্ষে এবার জোড়া গোল করলেন কেইন। তাঁর জোড়া গোলে বায়ার্ন জিতেছে ৪-২ ব্যবধানে। এই জয়ে বুন্দেসলিগার পয়েন্ট তালিকার শীর্ষে উঠেছে বায়ার্ন এবং এর মধ্য দিয়ে কেইন ভাঙলেন বুন্দেসলিগার গোলের একটি রেকর্ডও।', '<p>লিগ বদলেছে, দল বদলেছে, কিন্তু বদলাননি হ্যারি কেইন। বদলায়নি তাঁর গোল করার ধারাও। বুন্দেসলিগায় হেইডেনহেইমের বিপক্ষে এবার জোড়া গোল করলেন কেইন। তাঁর জোড়া গোলে বায়ার্ন জিতেছে ৪-২ ব্যবধানে। এই জ', 'nbbvvn', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '69/কেইনের-রেকর্ড,-এমবাপ্পের-হ্যাটট্রিকেও-খুশি-নন-এনরিকে'),
(70, 1062, 7, 10, 1, 1, 1, 'সংবাদ সম্মেলনে আর্থার, ‘বাবরকে বেড়ে ওঠার সুযোগ দিতে হবে’', NULL, NULL, 'public/postimages/6550839b1e4a0.png', 'পাকিস্তানের বিশ্বকাপ শেষ। ইংল্যান্ডের কাছে হেরে পাকিস্তান বিশ্বকাপ শেষ করেছে পয়েন্ট তালিকার পাঁচ নম্বরে থেকে। বিশ্বকাপ শেষে পাকিস্তান ক্রিকেটের সবচেয়ে বড় প্রশ্ন হচ্ছে, বাবর আজম কি অধিনায়ক হিসেবে থাকছেন?', '<p>পাকিস্তানের বিশ্বকাপ শেষ। ইংল্যান্ডের কাছে হেরে পাকিস্তান বিশ্বকাপ শেষ করেছে পয়েন্ট তালিকার পাঁচ নম্বরে থেকে। বিশ্বকাপ শেষে পাকিস্তান ক্রিকেটের সবচেয়ে বড় প্রশ্ন হচ্ছে, বাবর আজম কি অধিনায়ক', 'cricket', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '70/সংবাদ-সম্মেলনে-আর্থার,-‘বাবরকে-বেড়ে-ওঠার-সুযোগ-দিতে-হবে’'),
(71, 1062, 7, 9, 1, 1, 1, '‘মৌসুমের সেরা ম্যাচে’ ভ্যালেন্সিয়ার জালে রিয়ালের ৫ গোল', NULL, NULL, 'public/postimages/65508413a9904.png', 'লা লিগায় আগের ম্যাচে রায়ো ভায়েকানোর সঙ্গে গোলশূন্য ড্র করায় একটু চাপেই ছিল রিয়াল মাদ্রিদ। ভ্যালেন্সিয়ার বিপক্ষেও পয়েন্ট হারালে শীর্ষে থাকা জিরোনার সঙ্গে ব্যবধান আরও বেড়ে যেত। তবে আগের ম্যাচে ড্রয়ের ধাক্কা সামলে দারুণভাবে ঘুরে দাঁড়িয়েছে রিয়াল। ভ্যালেন্সিয়াকে ৫-১ গোলে উড়িয়ে দিয়েছে তারা।', '<p>লা লিগায় আগের ম্যাচে রায়ো ভায়েকানোর সঙ্গে গোলশূন্য ড্র করায় একটু চাপেই ছিল রিয়াল মাদ্রিদ। ভ্যালেন্সিয়ার বিপক্ষেও পয়েন্ট হারালে শীর্ষে থাকা জিরোনার সঙ্গে ব্যবধান আরও বেড়ে যেত। তবে আগের ম্যা', 'cric', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '71/‘মৌসুমের-সেরা-ম্যাচে’-ভ্যালেন্সিয়ার-জালে-রিয়ালের-৫-গোল'),
(72, 1063, 14, 36, 1, 1, 1, '২৪ হলে আদর-প্রকৃতির ‘যন্ত্রণা’', NULL, NULL, 'public/postimages/65509bbc3c168.png', 'গতকাল শুক্রবার মুক্তি পেয়েছে ভালোবাসা ও অ্যাকশননির্ভর গল্পে নির্মিত চিত্রনায়ক আদর আজাদ ও অভিনেত্রী মানসী প্রকৃতি জুটির সিনেমা ‘যন্ত্রণা’। ১০ নভেম্বর থেকে দেশজুড়ে ২৪টি প্রেক্ষাগৃহে সিনেমাটি চলছে। আবদুল্লাহ জহির বাবুর গল্পে সিনেমাটি পরিচালনা করেছেন তরুণ নির্মাতা আরিফুর জামান।', '<p>গতকাল শুক্রবার মুক্তি পেয়েছে ভালোবাসা ও অ্যাকশননির্ভর গল্পে নির্মিত চিত্রনায়ক আদর আজাদ ও অভিনেত্রী মানসী প্রকৃতি জুটির সিনেমা ‘যন্ত্রণা’। ১০ নভেম্বর থেকে দেশজুড়ে ২৪টি প্রেক্ষাগৃহে সিনেমাটি', 'dhaka', NULL, 1, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '72/২৪-হলে-আদর-প্রকৃতির-‘যন্ত্রণা’'),
(73, 1063, 14, 38, 1, 1, 1, 'নজরুলের গানের বিকৃতি: পশ্চিমবঙ্গে তীব্র নিন্দা এ আর রহমানের', NULL, NULL, 'public/postimages/65509c225ec16.png', 'বাংলাদেশের মুক্তিযুদ্ধ নিয়ে নির্মিত ওটিটি প্ল্যাটফর্মে একটি হিন্দি ছবির একটি গান নিয়ে প্রবল বিতর্ক দেখা দিয়েছে পশ্চিমবঙ্গে। গানটি নিয়ে অসন্তুষ্ট বাংলাদেশের শিল্পীসমাজও। কারণ, গানটি বাংলাদেশ ও পশ্চিমবঙ্গে জনপ্রিয় গানগুলোর অন্যতম।', '<p>বাংলাদেশের মুক্তিযুদ্ধ নিয়ে নির্মিত ওটিটি প্ল্যাটফর্মে একটি হিন্দি ছবির একটি গান নিয়ে প্রবল বিতর্ক দেখা দিয়েছে পশ্চিমবঙ্গে। গানটি নিয়ে অসন্তুষ্ট বাংলাদেশের শিল্পীসমাজও। কারণ, গানটি বাং', 'dhaka', NULL, NULL, 1, 1, 1, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '73/নজরুলের-গানের-বিকৃতি:-পশ্চিমবঙ্গে-তীব্র-নিন্দা-এ-আর-রহমানের'),
(74, 1063, 14, 37, 1, 1, 1, 'অশ্লীল পোশাক–আশাক হয় না, অশ্লীল মানুষের আচরণ হয়, ডিপজলের উদ্দেশে বললেন ইধিকা', NULL, NULL, 'public/postimages/6550aa1c4b8a0.png', 'বাংলাদেশি সিনেমায় অশ্লীলতা ছড়ানোর জন্য খল অভিনেতা ডিপজলকে দায়ী করেন অনেকে। সংলাপ ও অঙ্গভঙ্গি ছিল আপত্তিকর, বলেন সমসাময়িক চলচ্চিত্র সমালোচকেরা। দর্শকেরা চলচ্চিত্রবিমুখ হয়ে পড়েন।', '<p>বাংলাদেশি সিনেমায় অশ্লীলতা ছড়ানোর জন্য খল অভিনেতা ডিপজলকে দায়ী করেন অনেকে। সংলাপ ও অঙ্গভঙ্গি ছিল আপত্তিকর, বলেন সমসাময়িক চলচ্চিত্র সমালোচকেরা। দর্শকেরা চলচ্চিত্রবিমুখ হয়ে পড়েন। সেই ডিপজল এ', 'dhaka', NULL, NULL, NULL, 1, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '74/অশ্লীল-পোশাক–আশাক-হয়-না,-অশ্লীল-মানুষের-আচরণ-হয়,-ডিপজলের-উদ্দেশে-বললেন-ইধিকা'),
(75, 1063, 14, 38, 1, 1, 1, 'রণবীর–আলিয়া যেখানে, শাকিব–সোনাল সেখানে', NULL, NULL, 'public/postimages/6550a9b742399.png', 'পরিচালক সূত্রে জানা গেছে, শাকিব ও সোনালকে নিয়ে ‘দরদ’ ছবির রোমান্টিক গানের দৃশ্য ধারণের কাজটি করা হয়েছে বারানসির সেই স্থানে, যেখানে রণবীর কাপুর ও আলিয়া ভাটের গানের দৃশ্য ধারণ করা হয়।', '<p>পরিচালক সূত্রে জানা গেছে, শাকিব ও সোনালকে নিয়ে ‘দরদ’ ছবির রোমান্টিক গানের দৃশ্য ধারণের কাজটি করা হয়েছে বারানসির সেই স্থানে, যেখানে রণবীর কাপুর ও আলিয়া ভাটের গানের দৃশ্য ধারণ করা হয়। কোন ছব', 'daka', NULL, 1, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '75/রণবীর–আলিয়া-যেখানে,-শাকিব–সোনাল-সেখানে'),
(76, 1063, 14, 37, 1, 1, 1, 'মুম্বাইয়ে পুরস্কৃত ‘বাড়ির নাম শাহানা’', NULL, NULL, 'public/postimages/6550a914c575f.png', 'জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিনেমাটি এ পুরস্কার জিতেছে।', '<p>জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন<span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল লীসা গাজী পরিচালিত প্রথম পূর্ণদৈর্ঘ্য কাহিনিচিত্র ‘বাড়ির নাম শাহানা’। ভারতের চলচ্চিত্র সমালোচক গিল্ডের সিদ্ধান্তে সিন</span><span style=\"font-size: 1rem;\">জিও মামি মুম্বাই চলচ্চিত্র উৎসবে ‘জেন্ডার সেনসিটিভিটি অ্যাওয়ার্ড’ জিতল 