(80, 1063, 8, 12, 1, 1, 1, 'অনেক কাছের বন্ধু আমাকে হাসপাতালে দেখতেও যায়নি...', NULL, NULL, 'public/postimages/65509a6c262ef.png', 'গল্পটা হুমায়ূন আহমেদের জীবন থেকে প্রেরণা নিয়ে লেখা। এক তরুণ বিদেশ থেকে পড়াশোনা করে দেশে ফিরে হুমায়ূন আহমেদের মতো লেখক হতে চায়। এরপর ‘দরিদ্রতার স্বাদ’ নিয়ে সে এক ভাড়া বাসায় ওঠে। সেখানে এক তরুণী তাকে পছন্দ করে। এরপর নানা ঘটনা ঘটতে থাকে।', '<p>গল্পটা হুমায়ূন আহমেদের জীবন থেকে প্রেরণা নিয়ে লেখা। এক তরুণ বিদেশ থেকে পড়াশোনা করে দেশে ফিরে হুমায়ূন আহমেদের মতো লেখক হতে চায়। এরপর ‘দরিদ্রতার স্বাদ’ নিয়ে সে এক ভাড়া বাসায় ওঠে। সেখানে এক ত', 'nbbvvn', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '80/অনেক-কাছের-বন্ধু-আমাকে-হাসপাতালে-দেখতেও-যায়নি...'),
(81, 1063, 8, 13, 1, 1, 1, 'টুটুলের সঙ্গে বিচ্ছেদের পর তানিয়া বললেন, সন্তানের পিতাকে তো কখনোই ছোট করব না', NULL, NULL, 'public/postimages/65509adc13a7f.png', 'দুই দিন পরপর পরিচালকের সঙ্গে কথা হচ্ছে। সাইন করতে চেয়েছিল। কিন্তু যুক্তরাষ্ট্রে চলে এসেছি। সাধারণত আমাদের এখানে দেখা যায়, হিরো-হিরোইননির্ভর গল্প। এটা প্যারালাল দুই নারীর গল্প। তারপর একটা রেখায় গিয়ে মিলেছে।', '<p>দুই দিন পরপর পরিচালকের সঙ্গে কথা হচ্ছে। সাইন করতে চেয়েছিল। কিন্তু যুক্তরাষ্ট্রে চলে এসেছি। সাধারণত আমাদের এখানে দেখা যায়, হিরো-হিরোইননির্ভর গল্প। এটা প্যারালাল দুই নারীর গল্প। তারপর একটা র', 'dhaka', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '81/টুটুলের-সঙ্গে-বিচ্ছেদের-পর-তানিয়া-বললেন,-সন্তানের-পিতাকে-তো-কখনোই-ছোট-করব-না'),
