(106, 1062, 13, 16, 1, 1, 1, 'হজের নিবন্ধন শুরু ১৫ নভেম্বর', NULL, NULL, 'public/postimages/655078f85a581.jpg', '২০২৪ সালের হজের নিবন্ধন বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ধর্ম বিষয়ক মন্ত্রণালয়। এতে বলা হয়, সরকারি ও বেসরকারি ব্যবস্থাপনার (হজ এজেন্সি) হজযাত্রীরা ১৫ নভেম্বর থেকে নিবন্ধনের টাকা জমা দিতে পারবেন। নিবন্ধনের টাকা জমা নেওয়া হবে ১০ ডিসেম্বর পর্যন্ত।', '<p>২০২৪ সালের হজের নিবন্ধন বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ধর্ম বিষয়ক মন্ত্রণালয়। এতে বলা হয়, সরকারি ও বেসরকারি ব্যবস্থাপনার (হজ এজেন্সি) হজযাত্রীরা ১৫ নভেম্বর থেকে নিবন্ধনের টাকা জমা দিতে পারবেন', 'hajj', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '106/হজের-নিবন্ধন-শুরু-১৫-নভেম্বর'),
(107, 1062, 13, 17, 1, 1, 1, 'নোয়াখালীতে ফসলের মাঠে বাদামি গাছফড়িংয়ের উপদ্রব, পাকার আগেই ধান কাটছেন কৃষকেরা', NULL, NULL, 'public/postimages/655079e6c79ec.png', 'নোয়াখালীর শস্যভান্ডার খ্যাত সুবর্ণচর উপজেলায় আমন ধানের খেতে বেড়েছে বাদামি গাছফড়িংয়ের উপদ্রব। ধান পাকার মুহূর্তে এই পোকার উপদ্রবে নষ্ট হচ্ছে খেত। এতে দুশ্চিন্তায় পড়েছেন চাষিরা। এ অবস্থায় কৃষকদের কেউ কেউ পুরোপুরি পাকার আগেই কেটে ফেলছেন ধান, কেউ আবার কীটনাশক ছিটিয়ে ফসল রক্ষার চেষ্টা করছেন।', '<p>নোয়াখালীর শস্যভান্ডার খ্যাত সুবর্ণচর উপজেলায় আমন ধানের খেতে বেড়েছে বাদামি গাছফড়িংয়ের উপদ্রব। ধান পাকার মুহূর্তে এই পোকার উপদ্রবে নষ্ট হচ্ছে খেত। এতে দুশ্চিন্তায় পড়েছেন চাষিরা। এ অবস্থায় কৃ', 'agriculture', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '107/নোয়াখালীতে-ফসলের-মাঠে-বাদামি-গাছফড়িংয়ের-উপদ্রব,-পাকার-আগেই-ধান-কাটছেন-কৃষকেরা'),
(108, 1062, 13, 16, 1, 1, 1, 'সুরা ইখলাসের শিক্ষা', NULL, NULL, 'public/postimages/65507a9619889.png', 'সুরা ইখলাস পবিত্র কোরআনের ১১২তম সুরা। এটি মক্কায় অবতীর্ণ হয়েছে। এর রুকু ১, আয়াত ৪। এই সুরায় তওহিদ বা আল্লাহর একত্ববাদের ঘোষণার পর আল্লাহর সন্তানসন্ততি আছে বলে যে ভ্রান্ত ধারণা করা হয়, তার প্রতিবাদ করা হয়েছে। আল্লাহ সব অভাবের অতীত এবং তাঁর কোনো তুলনা নেই।', '<p>সুরা ইখলাস পবিত্র কোরআনের ১১২তম সুরা। এটি মক্কায় অবতীর্ণ হয়েছে। এর রুকু ১, আয়াত ৪। এই সুরায় তওহিদ বা আল্লাহর একত্ববাদের ঘোষণার পর আল্লাহর সন্তানসন্ততি আছে বলে যে ভ্রান্ত ধারণা করা হয়, তা', 'islam', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '108/সুরা-ইখলাসের-শিক্ষা'),
(109, 1062, 13, 16, 1, 1, 1, 'খিজির (আ.)–এর সঙ্গী ‎মুসা (আ.)', NULL, NULL, 'public/postimages/65507b1f1a641.png', 'হজরত উবাই ইবনে কাব (রা.)-র বরাতে এই হাদিসটির বর্ণনা আছে। তিনি নবী (সা.)-এর কাছে নিচের ঘটনাটি শুনেছেন।', '<p>হজরত উবাই ইবনে কাব (রা.)-র বরাতে এই হাদিসটির বর্ণনা আছে। তিনি নবী (সা.)-এর কাছে নিচের ঘটনাটি শুনেছেন।<span style=\"font-size: 1rem;\">একবার মুসা (আ.) বনি ইসরাইলের এক সমাবেশে ভাষণ দেওয়ার জন্য', 'islam', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '109/খিজির-(আ.)–এর-সঙ্গী-%E2%80%8Eমুসা-(আ.)'),
(110, 1062, 14, 36, 1, 1, 1, 'জামায়াত নিয়ে ইকবাল হাসানের বক্তব্য তাঁর ব্যক্তিগত: রিজভী', NULL, NULL, 'public/postimages/6550a06b2ee60.png', 'জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শনিবার এক বিবৃতিতে তিনি বলেন, ইকবাল হাসান মাহমুদের বক্তব্য বা মতামত একান্তই তাঁর নিজস্ব।', '<p>জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ<span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-size: 1rem;\">জামায়াতে ইসলামী সম্পর্কে বিএনপির স্থায়ী কমিটির সদস্য জনাব ইকবাল হাসান মাহমুদের (টুকু) বক্তব্যের সঙ্গে দলের কোনো সম্পর্ক নেই বলে জানিয়েছেন দলটির জ্যেষ্ঠ যুগ্ম মহাসচিব রুহুল কবির রিজভী। আজ শ</span><span style=\"font-si