(113, 1063, 2, 3, NULL, NULL, 1, 'ঢাকায় পুলিশের গাড়িতে আগুনের ঘটনায় দুজন গ্রেপ্তার', NULL, NULL, 'public/postimages/655320281b0f4.jpg', 'এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!', '<p>এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!<br>', 'nbbvvn', NULL, 1, 1, 1, 1, '14-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '113/ঢাকায়-পুলিশের-গাড়িতে-আগুনের-ঘটনায়-দুজন-গ্রেপ্তার'),
(114, 1049, 10, 39, NULL, NULL, 1, 'দেয়ালঘেরা বাড়িটিতে তিন খুন নিয়ে নানা জল্পনা', NULL, NULL, 'public/postimages/65bcf21f736a8.jpg', 'গলা কাটা রক্তাক্ত অবস্থায় বাড়ির বাইরে এসে ঢলে পড়েন আশিকুল হক মোল্লা (৪০)। তৎক্ষণাৎ স্থানীয় লোকজন এগিয়ে তাঁকে উদ্ধার করে হাসপাতালে নেন। পরে বাড়ির শয়নকক্ষে একটি বিছানায় তাঁর স্ত্রী তহুরা বেগম (৩০), দুই শিশুকন্যা আয়েশা আক্তার (১১) ও যারিনের (৬) লাশ পড়ে থাকতে দেখা যায়। তবে তিনটি লাশের শরীরেই রক্ত বা কোনো জখমের চিহ্ন নেই।', '<p>গলা কাটা রক্তাক্ত অবস্থায় বাড়ির বাইরে এসে ঢলে পড়েন আশিকুল হক মোল্লা (৪০)। তৎক্ষণাৎ স্থানীয় লোকজন এগিয়ে তাঁকে উদ্ধার করে হাসপাতালে নেন। পরে বাড়ির শয়নকক্ষে একটি বিছানায় তাঁর স্ত্রী তহুরা বেগম (৩০), দুই শিশুকন্যা আয়েশা আক্তার (১১) ও যারিনের (৬) লাশ পড়ে থাকতে দেখা যায়। তবে তিনটি লাশের শরীরেই রক্ত বা কোনো জখমের চিহ্ন নেই।</p><p><span style=\"font-size: 1rem;\">ঘটনাটিকে রহস্যজনক বলছে পুলিশ। আত্মীয়স্বজন ও প্রতিবেশীদের কেউই ঘটনা সম্পর্কে সুস্পষ্ট কোনো ধারণা দিতে পারছেন না। আশিকুল হক তাঁর স্ত্রী ও দুই মেয়েকে হত্যা করে আত্মহত্যার চেষ্টা করেছেন, নাকি অন্য কেউ তাঁদের হত্যা করেছে, তা নিয়ে চলছে জল্পনা। নিহত তিনজনের শরীরে জখমের চিহ্ন না থাকায় তাঁদের শ্বাসরোধে নাকি অন্য কোনোভাবে হত্যা করা হয়েছে, সেটিও নিশ্চিত নয়। আবার একই বিছানায় লাশ তিনটি পাশাপাশি রাখা নিয়ে পুরো হত্যাপ্রক্রিয়া নিয়ে তৈরি হয়েছে ধোঁয়াশা।</span><br></p>', 'দেয়ালঘেরা বাড়িটিতে তিন খুন নিয়ে নানা জল্পনা', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '114/দেয়ালঘেরা-বাড়িটিতে-তিন-খুন-নিয়ে-নানা-জল্পনা'),
(115, 1049, 10, 40, NULL, NULL, 1, 'ট্রান্সজেন্ডার নারীকে নৃশংসভাবে হত্যায় বিচারের', NULL, NULL, 'public/postimages/65bcf2f026e73.png', 'যুক্তরাজ্যে ট্রান্সজেন্ডার এক নারীকে হত্যা করায় ১৬ বছর বয়সী দুজন বিচারের মুখোমুখি হয়েছে। আজ শুক্রবার অভিযুক্ত দুজনের বিচারের রায় হওয়ার কথা রয়েছে।', '<p>যুক্তরাজ্যে ট্রান্সজেন্ডার এক নারীকে হত্যা করায় ১৬ বছর বয়সী দুজন বিচারের মুখোমুখি হয়েছে। আজ শুক্রবার অভিযুক্ত দুজনের বিচারের রায় হওয়ার কথা রয়েছে।</p><p><span style=\"font-size: 1rem;\">ছুরিকাঘাত করে&nbsp; নৃশংস এই হত্যাকাণ্ড ও বিচারের ঘটনা সংবাদমাধ্যমে বেশ আলোচনার জন্ম দিয়েছে।</span><br></p><p><span style=\"font-size: 1rem;\">ঘটনাটি গত বছরের ফেব্রুয়ারির। যুক্তরাজ্যের উত্তর-পশ্চিমাঞ্চলের ওয়ারিংটন নামে একটি শহরে ১৬ বছর বয়সী ট্রান্সজেন্ডার নারী ব্রিয়ান্না ঘেকে হত্যা করা হয়। একটি পার্ক থেকে উদ্ধার করা হয় ব্রিয়ান্নার মরদেহ।</span><br></p><p>মাথা, ঘাড়, বুক আর শরীরের পেছনের অংশে ২৮ বার ছুরিকাঘাত করে ব্রিয়ান্নাকে হত্যা করা হয়েছিল। ওই সময় এই হত্যাকাণ্ড দেশি-বিদেশি সংবাদমাধ্যমে শোরগোল ফেলে দেয়। স্তম্ভিত হন যুক্তরাজ্যবাসী।</p><p><span style=\"font-size: 1rem;\">ব্রিয়ান্নাকে হত্যার অভিযোগ ওঠে ১৫ বছর বয়সী দুজনের বিরুদ্ধে। এই দুজনের বয়স এখন ১৬ বছর। যুক্তরাজ্যে অপ্রাপ্তবয়স্ক অভিযুক্তদের নাম-পরিচয় প্রকাশ করা হয় না। তবে বিচারক সম্মত হওয়ায় আজ রায় ঘোষণার পর দুজনের নাম প্রকাশ করা হবে।</span><br></p><p><br></p>', 'ট্রান্সজেন্ডার নারীকে নৃশংসভাবে হত্যায় বিচারের', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '115/ট্রান্সজেন্ডার-নারীকে-নৃশংসভাবে-হত্যায়-বিচারের-মুখোমুখি-১৬-বছরের-দুজন'),
(117, 1028, 10, 41, NULL, NULL, 1, 'নারীর ব্যক্তিগত ভিডিও ছড়িয়ে দেওয়ার ভয় দেখিয়ে', NULL, NULL, 'public/postimages/65bcf78b1a3bf.png', 'নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।', '<p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p><p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p><p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p>', 'নারীর ব্যক্তিগত ভিডিও ছড়িয়ে দেওয়ার ভয় দেখিয়ে চাঁদা দাবি, গ্রেপ্তার ১', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '117/নারীর-ব্যক্তিগত-ভিডিও-ছড়িয়ে-দেওয়ার-ভয়-দেখিয়ে-চাঁদা-দাবি,-গ্রেপ্তার-১'),
(119, 1025, 6, 27, NULL, NULL, 1, 'ভিন্ন মাস, বছর, এমনকি ভিন্ন দশকে জন্ম নিয়েও তাঁরা যমজ', NULL, NULL, 'public/postimages/65bcf9c5398fc.png', 'যমজ সন্তানের অপেক্ষায় ছিলেন আয়ারল্যান্ডের কিলকেনি শহরের বাসিন্দা ক্রিস ও মারিয়া জোনস এলিয়ট দম্পতি। সন্তান হওয়ার সম্ভাব্য তারিখ ছিল ২০১৩ সালের ২১ সেপ্টেম্বর। কিন্তু গর্ভধারণের মাত্র ২৩ সপ্তাহ পাঁচ দিনের মাথায় তলপেটে তীব্র চাপ অনুভব করেন মারিয়া। হাসপাতালে ভর্তি করা হয় তাঁকে।', '<p>যমজ সন্তানের অপেক্ষায় ছিলেন আয়ারল্যান্ডের কিলকেনি শহরের বাসিন্দা ক্রিস ও মারিয়া জোনস এলিয়ট দম্পতি। সন্তান হওয়ার সম্ভাব্য তারিখ ছিল ২০১৩ সালের ২১ সেপ্টেম্বর। কিন্তু গর্ভধারণের মাত্র ২৩ সপ্তাহ পাঁচ দিনের মাথায় তলপেটে তীব্র চাপ অনুভব করেন মারিয়া। হাসপাতালে ভর্তি করা হয় তাঁকে। ২০১৩ সালের ১ জুন জন্মগ্রহণ করে প্রথম যমজ অ্যামি। তার ওজন ছিল মাত্র আধা কেজি। সে লড়ছিল ইনকিউবেটরে। ওদিকে তার যমজ বোন ক্যাটি লড়ছিল মায়ের ডিম্বাশয়ে। অবশেষে অ্যামির জন্মের ৮৭ দিন পর, ২৭ আগস্ট জন্ম নেয় ক্যাটি।&nbsp;</p><p><span style=\"font-size: 1rem;\">যুক্তরাষ্ট্রের টেনেসি অঙ্গরাজ্যের জেফারসন সিটির দম্পতি ক্রিস্টেন ও ইয়ান মিলার। তাঁদের যমজ সন্তান হওয়ার সম্ভাব্য সময় ছিল ২০১৬ সালের জুন। কিন্তু ফেব্রুয়ারিতেই জটিলতা দেখা দেওয়ায় ক্রিস্টেনকে হাসপাতালে ভর্তি করা হয়। ২০১৬ সালের ১৪ ফেব্রুয়ারি গর্ভধারণের ২৪ সপ্তাহ এক দিনের মাথায় জন্ম নেয় যমজ পুত্র মিকা। ঘণ্টাখানেকের মধ্যে মিকার যমজ বোন মেডিলিনও চলে আসবে—এমনটাই প্রত্যাশা করছিলেন চিকিৎসক। তবে কিছুক্ষণের মধ্যেই তিনি বুঝতে পারেন, মেডিলিনের জন্ম শিগগিরই হচ্ছে না। অবশেষে মিকার জন্মের ৩৮ দিন পর পৃথিবীতে আসে মেডিলিন।&nbsp;</span><br></p>', 'ভিন্ন মাস, বছর, এমনকি ভিন্ন দশকে জন্ম নিয়েও তাঁরা যমজ', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '119/ভিন্ন-মাস,-বছর,-এমনকি-ভিন্ন-দশকে-জন্ম-নিয়েও-তাঁরা-যমজ'),
(120, 840, 2, 3, NULL, NULL, 1, 'নিরাপত্তার কারণে মিয়ানমার সীমান্তে যানবাহন', NULL, NULL, 'public/postimages/65bf683dd63e1.png', 'বান্দরবানের নাইক্ষ্যংছড়ি সীমান্তের ওপারে মিয়ানমারে বিদ্রোহী দল আরাকান আর্মির সঙ্গে দেশটির সীমান্তরক্ষী বাহিনী বর্ডার গার্ড পুলিশের (বিজিপি) তীব্র গোলাগুলি হচ্ছে। এ অবস্থায় পাঁচটি সরকারি প্রাথমিক বিদ্যালয় বন্ধ ও সীমান্তবর্তী কয়েকটি সড়কের যানবাহন চলাচল নিয়ন্ত্রণ করার ঘোষণা দিয়েছে জেলা প্রশাসন।', '<p>বান্দরবানের নাইক্ষ্যংছড়ি সীমান্তের ওপারে মিয়ানমারে বিদ্রোহী দল আরাকান আর্মির সঙ্গে দেশটির সীমান্তরক্ষী বাহিনী বর্ডার গার্ড পুলিশের (বিজিপি) তীব্র গোলাগুলি হচ্ছে। এ অবস্থায় পাঁচটি সরকারি প্রাথমিক বিদ্যালয় বন্ধ ও সীমান্তবর্তী কয়েকটি সড়কের যানবাহন চলাচল নিয়ন্ত্রণ করার ঘোষণা দিয়েছে জেলা প্রশাসন।</p><p><br></p><p>সীমান্তের ওপারে মিয়ানমারে গোলা নিক্ষেপ ও গোলাগুলির কারণে স্থানীয় লোকজন আতঙ্কিত হয়ে পড়ায় এই সিদ্ধান্ত নেওয়া হয়েছে। আজ রোববার দুপুরের বান্দরবান জেলা প্রশাসক শাহ্ মোজাহিদ উদ্দিন প্রথম আলোকে এ তথ্যটি নিশ্চিত করেন।</p><p><br></p><p>শাহ্ মোজাহিদ উদ্দিন বলেন, গতকাল শনিবার রাত থেকে হঠাৎ গোলাগুলি বেড়ে যায়। সেই পরিপ্রেক্ষিতে নিরাপত্তার বিষয়টি চিন্তা করে ঘুমধুম ও তুমব্রু সীমান্তের কাছে পাঁচটি প্রাথমিক বিদ্যালয় বন্ধ ঘোষণা করা হয়েছে। বন্ধ হওয়া বিদ্যালয়গুলো হলো—বাইশফাড়ী সরকারি প্রাথমিক বিদ্যালয়, ভাজাবনিয়া সরকারি প্রাথমিক বিদ্যালয়, তুমব্রু সরকারি প্রাথমিক বিদ্যালয়, তুমব্রু পশ্চিমকুল সরকারি প্রাথমিক বিদ্যালয় ও দক্ষিণ ঘুমধুম সরকারি প্রাথমিক বিদ্যালয়।বান্দরবানের নাইক্ষ্যংছড়ি সীমান্তের ওপারে মিয়ানমারে বিদ্রোহী দল আরাকান আর্মির সঙ্গে দেশটির সীমান্তরক্ষী বাহিনী বর্ডার গার্ড পুলিশের (বিজিপি) তীব্র গোলাগুলি হচ্ছে। এ অবস্থায় পাঁচটি সরকারি প্রাথমিক বিদ্যালয় বন্ধ ও সীমান্তবর্তী কয়েকটি সড়কের যানবাহন চলাচল নিয়ন্ত্রণ করার ঘোষণা দিয়েছে জেলা প্রশাসন।</p><p><br></p><p>সীমান্তের ওপারে মিয়ানমারে গোলা নিক্ষেপ ও গোলাগুলির কারণে স্থানীয় লোকজন আতঙ্কিত হয়ে পড়ায় এই সিদ্ধান্ত নেওয়া হয়েছে। আজ রোববার দুপুরের বান্দরবান জেলা প্রশাসক শাহ্ মোজাহিদ উদ্দিন প্রথম আলোকে এ তথ্যটি নিশ্চিত করেন।</p><p><br></p><p>শাহ্ মোজাহিদ উদ্দিন বলেন, গতকাল শনিবার রাত থেকে হঠাৎ গোলাগুলি বেড়ে যায়। সেই পরিপ্রেক্ষিতে নিরাপত্তার বিষয়টি চিন্তা করে ঘুমধুম ও তুমব্রু সীমান্তের কাছে পাঁচটি প্রাথমিক বিদ্যালয় বন্ধ ঘোষণা করা হয়েছে। বন্ধ হওয়া বিদ্যালয়গুলো হলো—বাইশফাড়ী সরকারি প্রাথমিক বিদ্যালয়, ভাজাবনিয়া সরকারি প্রাথমিক বিদ্যালয়, তুমব্রু সরকারি প্রাথমিক বিদ্যালয়, তুমব্রু পশ্চিমকুল সরকারি প্রাথমিক বিদ্যালয় ও দক্ষিণ ঘুমধুম সরকারি প্রাথমিক বিদ্যালয়।</p>', 'নিরাপত্তার কারণে মিয়ানমার সীমান্তে যানবাহন চলাচল নিয়ন্ত্রণ, পাঁচটি বিদ্যালয় বন্ধ ঘোষণা', NULL, 1, 1, 1, 1, '04-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '120/নিরাপত্তার-কারণে-মিয়ানমার-সীমান্তে-যানবাহন-চলাচল-নিয়ন্ত্রণ,-পাঁচটি-বিদ্যালয়-বন্ধ-ঘোষণা'),
(121, 836, 2, 5, NULL, NULL, 1, 'জীবিত থেকেও জাতীয় পরিচয়পত্রে মৃত তছলিম', NULL, NULL, 'public/postimages/65bf69b65ea9c.png', 'জীবিত থেকেও জাতীয় পরিচয়পত্রে নামের পাশে মৃত উল্লেখ থাকায় বিপাকে পড়েছেন মো. তছলিম (৬৭) নামের এক ব্যক্তি। তিনি এখনো হজের নিবন্ধন করতে পারেননি। জাতীয় পরিচয়পত্রে নিজের নাম ঠিক করার জন্য এখন দ্বারে দ্বারে ঘুরছেন।', '<p>জীবিত থেকেও জাতীয় পরিচয়পত্রে নামের পাশে মৃত উল্লেখ থাকায় বিপাকে পড়েছেন মো. তছলিম (৬৭) নামের এক ব্যক্তি। তিনি এখনো হজের নিবন্ধন করতে পারেননি। জাতীয় পরিচয়পত্রে নিজের নাম ঠিক করার জন্য এখন দ্বারে দ্বারে ঘুরছেন।</p><p>মো. তছলিম লক্ষ্মীপুরের রায়পুর উপজেলার উদমারা গ্রামের বাসিন্দা। তাঁর বাবার নাম মুনছুর আহাম্মদ। তছলিম বলেন, হজে যাওয়ার জন্য গত ৩১ জানুয়ারি তছলিম জাতীয় পরিচয়পত্রের অনলাইন কপি তুলতে একটি কম্পিউটার দোকানে যান। কিন্তু অনলাইনে তা পাওয়া যায়নি। এরপর উপজেলা নির্বাচন অফিসে যান তিনি। সেখানে গিয়ে জানতে পারেন তিনি মৃত।জীবিত থেকেও জাতীয় পরিচয়পত্রে নামের পাশে মৃত উল্লেখ থাকায় বিপাকে পড়েছেন মো. তছলিম (৬৭) নামের এক ব্যক্তি। তিনি এখনো হজের নিবন্ধন করতে পারেননি। জাতীয় পরিচয়পত্রে নিজের নাম ঠিক করার জন্য এখন দ্বারে দ্বারে ঘুরছেন।</p><p>মো. তছলিম লক্ষ্মীপুরের রায়পুর উপজেলার উদমারা গ্রামের বাসিন্দা। তাঁর বাবার নাম মুনছুর আহাম্মদ। তছলিম বলেন, হজে যাওয়ার জন্য গত ৩১ জানুয়ারি তছলিম জাতীয় পরিচয়পত্রের অনলাইন কপি তুলতে একটি কম্পিউটার দোকানে যান। কিন্তু অনলাইনে তা পাওয়া যায়নি। এরপর উপজেলা নির্বাচন অফিসে যান তিনি। সেখানে গিয়ে জানতে পারেন তিনি মৃত।</p>', 'জীবিত থেকেও জাতীয় পরিচয়পত্রে মৃত তছলিম', NULL, 1, 1, 1, 1, '04-02-2024', 'February', NULL, NULL, NULL, 1, NULL, NULL),
(122, 836, 2, 5, NULL, NULL, 1, 'হিজড়া-ট্রান্সজেন্ডার নিয়ে কেন এত বিতর্ক', NULL, NULL, 'public/postimages/65bf6a4edf82e.png', 'ট্রান্সওম্যান (রূপান্তরিত নারী) জয়া সিকদার। মাত্র ১৪ বছর বয়সে তিনি পটুয়াখালীর বাড়ি ছেড়ে ঢাকায় আসতে বাধ্য হন।   ছোটবেলায় জয়াকে তাঁর বাবা বাইরে নিয়ে যেতে চাইতেন। কিন্তু তাঁর হাঁটাচলা কেন পুরুষালি নয়, তা নিয়ে তাঁকে নানা কথা শুনতে হতো।', '<p>ট্রান্সওম্যান (রূপান্তরিত নারী) জয়া সিকদার। মাত্র ১৪ বছর বয়সে তিনি পটুয়াখালীর বাড়ি ছেড়ে ঢাকায় আসতে বাধ্য হন।&nbsp;</p><p>ছোটবেলায় জয়াকে তাঁর বাবা বাইরে নিয়ে যেতে চাইতেন। কিন্তু তাঁর হাঁটাচলা কেন পুরুষালি নয়, তা নিয়ে তাঁকে নানা কথা শুনতে হতো।&nbsp;</p><p>সপ্তম শ্রেণিতে পড়াকালে স্কুলে হয়রানি-কটূক্তির শিকার হয়ে জয়ার পড়াশোনা বন্ধ হয়ে যায়। মেয়ের জন্য সমাজে মুখ দেখাতে পারেন না—এ ক্ষোভে বাবা একদিন জয়ার মাকে মারধর করেন।&nbsp;</p><p>জয়া বলেন, সন্তানের কারণে সন্তানের সামনে মাকে বাবার মারধরের পর তো সন্তানের পক্ষে আর বাড়িতে থাকা সম্ভব হয় না।&nbsp;</p><p>কৈশোরে ঢাকায় পা দেওয়ার পর পদে পদে যৌন হয়রানিসহ বিভিন্ন হয়রানির সম্মুখীন হন জয়া। এই শহরে জয়া পোশাক কারখানাসহ বিভিন্ন জায়গায় একটি চাকরি চেয়েও পাননি।&nbsp;</p><p>পোশাক কারখানার নিরাপত্তাকর্মী জয়াকে চাকরি পাইয়ে দেওয়ার আশ্বাস দিয়ে তাঁকে সারা দিন বসিয়ে রেখেছিলেন। সেই নিরাপত্তাকর্মীই রাতে জয়াকে যৌনপীড়ন করেন।&nbsp;</p><p>একসময় জয়া এক ‘গুরুমায়ের’ আশ্রয়ে থাকতে শুরু করেন। হিজড়া যৌনকর্মীদের সঙ্গে তাঁকেও একই কাজ করতে হয়। জয়ার ভাষ্য, তিনি ক্ষুধার যন্ত্রণায় এই পেশা বেছে নিতে বাধ্য হয়েছিলেন।&nbsp;</p><p>জয়ার জীবনে গত শতকের নব্বইয়ের দশকে ঘটে যাওয়া ঘটনা এগুলো। তারপর তিনি কেয়ার বাংলাদেশ ও আন্তর্জাতিক উদরাময় গবেষণা কেন্দ্র, বাংলাদেশে (আইসিডিডিআরবি) কাজ করেন। নেতৃত্ব বিকাশের বিভিন্ন প্রশিক্ষণ নেওয়ার সুযোগ পান তিনি। জয়ার এখনকার পরিচয়—তিনি একজন অধিকারকর্মী। তিনি ট্রান্সজেন্ডার মানুষের অধিকার রক্ষায় কাজ করছেন।&nbsp;</p><p>জয়া জানান, তিনি যখন হিজড়া কমিউনিটিতে ছিলেন, তখন নিজেকে ‘হিজড়া’ পরিচয় দিতেন। এ সংস্কৃতি থেকে বের হওয়ার পর তিনি নিজেকে ট্রান্সওম্যান বা রূপান্তরিত নারী হিসেবে পরিচয় দিচ্ছেন।&nbsp;</p>', 'হিজড়া-ট্রান্সজেন্ডার নিয়ে কেন এত বিতর্ক', NULL, 1, 1, 1, 1, '04-02-2024', 'February', NULL, NULL, NULL, 1, NULL, NULL),
(123, 829, 6, 27, NULL, NULL, 1, 'চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু', NULL, NULL, 'public/postimages/65bf726cb11f5.png', 'চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু হয়েছে। গতকাল শনিবার এ দাবানলের শুরু। আজ রোববারও তা অব্যাহত আছে। মৃতের সংখ্যা বাড়তে পারে বলে আশঙ্কা করা হচ্ছে।', '<p>চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু হয়েছে। গতকাল শনিবার এ দাবানলের শুরু। আজ রোববারও তা অব্যাহত আছে। মৃতের সংখ্যা বাড়তে পারে বলে আশঙ্কা করা হচ্ছে।</p><p>কর্তৃপক্ষ জানিয়েছে, অনেক ঘরবাড়ি পুড়ে গেছে। কোথাও কোথাও রাস্তায় মরদেহ পড়ে থাকতে দেখা গেছে।</p><p>দাবালের জেরে দেশটির মধ্য ও দক্ষিণাঞ্চলে জরুরি অবস্থা জারি করেছেন প্রেসিডেন্ট গ্যাব্রিয়েল বোরিক। শুষ্ক আবহওয়া ও উচ্চ তাপমাত্রা (৪০ ডিগ্রি সেলসিয়াস) এ সংকটকে আরও ভয়াবহ করে তুলেছে।</p><p>চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু হয়েছে। গতকাল শনিবার এ দাবানলের শুরু। আজ রোববারও তা অব্যাহত আছে। মৃতের সংখ্যা বাড়তে পারে বলে আশঙ্কা করা হচ্ছে।</p><p>কর্তৃপক্ষ জানিয়েছে, অনেক ঘরবাড়ি পুড়ে গেছে। কোথাও কোথাও রাস্তায় মরদেহ পড়ে থাকতে দেখা গেছে।</p><p>দাবানলের জেরে দেশটির মধ্য ও দক্ষিণাঞ্চলে জরুরি অবস্থা জারি করেছেন প্রেসিডেন্ট গ্যাব্রিয়েল বোরিক। শুষ্ক আবহওয়া ও উচ্চ তাপমাত্রা (৪০ ডিগ্রি সেলসিয়াস) এ সংকটকে আরও ভয়াবহ করে তুলেছে।</p><p>চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু হয়েছে। গতকাল শনিবার এ দাবানলের শুরু। আজ রোববারও তা অব্যাহত আছে। মৃতের সংখ্যা বাড়তে পারে বলে আশঙ্কা করা হচ্ছে।</p><p>কর্তৃপক্ষ জানিয়েছে, অনেক ঘরবাড়ি পুড়ে গেছে। কোথাও কোথাও রাস্তায় মরদেহ পড়ে থাকতে দেখা গেছে।</p><p>দাবানলের জেরে দেশটির মধ্য ও দক্ষিণাঞ্চলে জরুরি অবস্থা জারি করেছেন প্রেসিডেন্ট গ্যাব্রিয়েল বোরিক। শুষ্ক আবহওয়া ও উচ্চ তাপমাত্রা (৪০ ডিগ্রি সেলসিয়াস) এ সংকটকে আরও ভয়াবহ করে তুলেছে।</p><p><br></p>', 'চিলিতে দাবানলে অন্তত ৫১ জনের মৃত্যু', NULL, 1, 1, 1, 1, '04-02-2024', 'February', NULL, NULL, NULL, 1, NULL, NULL);

